import os

class AzureTranslatorClient:
    def __init__(self, api_key=None, region=None):
        self.api_key = api_key or os.environ.get("AZURE_TRANSLATOR_API_KEY")
        self.region = region or os.environ.get("AZURE_TRANSLATOR_REGION")
        if not self.api_key or not self.region:
            raise ValueError("Azure Translator API key and region must be provided or set as environment variables.")

    def get_config(self):
        return {
            "api_key": self.api_key,
            "region": self.region
        }

class TranslationRequest:
    def __init__(self, text, source_language, target_language):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language

class BatchTranslationRequest:
    def __init__(self, texts, source_language, target_language):
        self.texts = texts
        self.source_language = source_language
        self.target_language = target_language

class TranslationResponse:
    def __init__(self, text, source_language, target_language):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language

class BatchTranslationResponse:
    def __init__(self, translations, source_language, target_language):
        self.translations = translations
        self.source_language = source_language
        self.target_language = target_language

from google.cloud import contentsafety_v1
import os

def unsafe_copy_check(payload):
    client = contentsafety_v1.ContentSafetyServiceClient()
    project_id = os.environ.get("GCP_PROJECT_ID")
    if not project_id:
        raise ValueError("GCP_PROJECT_ID environment variable not set.")

    text_content = payload['text']

    # The parent format is "projects/{project}"
    parent = f"projects/{project_id}"

    request = contentsafety_v1.ScreenTextRequest(
        parent=parent,
        text_content=text_content,
    )

    response = client.screen_text(request=request)

    safety_ratings = []
    for category_rating in response.triggered_found_categories:
        safety_ratings.append({
            "category": contentsafety_v1.RiskAnalysis.RiskCategory(category_rating.category).name,
            "severity": category_rating.severity
        })

    return {"unsafe_content_findings": safety_ratings}
